//! Vink UI — the Leptos renderer of the shared token contract in `packages/ui-system/shared`.
//!
//! `tokens` and `catalog` are generated by `cargo xtask ui-tokens`; never edit them by hand.
//! [`UiRoot`] and [`ThemeScope`] receive preferences from their caller: the library reads no
//! storage, account, route or service, and the app keeps persistence and the pre-CSS bootstrap.
//! Styling goes through the `--vk-*` custom properties in `style/tokens.css`, so a scope's theme,
//! density, motion and typed role overrides reach every descendant.

#[rustfmt::skip]
pub mod catalog;
pub mod root;
pub mod theme;
#[rustfmt::skip]
pub mod tokens;
pub mod values;

pub use root::{ThemeScope, UiRoot};
pub use theme::{
    Density, MotionPreference, OverrideError, Preferences, ResolvedTheme, RoleOverride,
    ThemePreference,
};
pub use tokens::ColorRole;
